const string Dir="Assets/Scenes/Oasis/CoastalTerrain/Crags";static System.Random random=new System.Random(8573);static float R(float a,float b)=>(float)(a+random.NextDouble()*(b-a));static CoastalCragDetail(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("CoastalCragDetail.request")||EditorApplication.isCompiling)return;File.Delete("CoastalCragDetail.request");Run();}
class Geo{public List<Vector3> p=new List<Vector3>();public List<Vector2> uv=new List<Vector2>();public List<int> ids=new List<int>();public void Tri(Vector3 a,Vector3 b,Vector3 c){int n=p.Count;var normal=Vector3.Cross(b-a,c-a).normalized;p.AddRange(new[]{a,b,c});foreach(var v in new[]{a,b,c}){if(Mathf.Abs(normal.x)>Mathf.Abs(normal.y)&&Mathf.Abs(normal.x)>Mathf.Abs(normal.z))uv.Add(new Vector2(v.z,v.y)/9);else if(Mathf.Abs(normal.z)>Mathf.Abs(normal.y))uv.Add(new Vector2(v.x,v.y)/9);else uv.Add(new Vector2(v.x,v.z)/9);}ids.AddRange(new[]{n,n+1,n+2});}public Mesh Mesh(string name){var m=new Mesh{name=name,indexFormat=IndexFormat.UInt32};m.SetVertices(p);m.SetUVs(0,uv);m.SetTriangles(ids,0);m.RecalculateNormals();m.RecalculateBounds();return m;}}
