static bool Land(Terrain t,Vector2 p){var pos=t.transform.position;var size=t.terrainData.size;float x=(p.x-pos.x)/size.x,z=(p.y-pos.z)/size.z;if(x<=0||x>=1||z<=0||z>=1)return false;return !t.terrainData.IsHole(Mathf.FloorToInt(x*512),Mathf.FloorToInt(z*512));}
static void Shape(Geo geo,Terrain terrain,Vector2 center,float radius,float height,float angle,int sides,int seed){int n=sides==9?10:5;var points=new Vector3[n+1,n+1];float stretch=.52f+.25f*Mathf.PerlinNoise(seed*.71f,2.3f);float ca=Mathf.Cos(angle),sa=Mathf.Sin(angle);for(int z=0;z<=n;z++)for(int x=0;x<=n;x++){float u=x/(float)n*2-1,v=z/(float)n*2-1;float distortedU=u+.12f*Mathf.Sin(v*4.1f+seed)*Mathf.Sin(x*Mathf.PI/n);float distortedV=v+.1f*Mathf.Sin(u*5.4f+seed*.8f)*Mathf.Sin(z*Mathf.PI/n);float radial=Mathf.Sqrt(distortedU*distortedU+distortedV*distortedV);var local=new Vector2(distortedU,distortedV*stretch)*radius;var p=center+new Vector2(local.x*ca-local.y*sa,local.x*sa+local.y*ca);float ground=terrain.SampleHeight(new Vector3(p.x,0,p.y));float envelope=Mathf.Pow(Mathf.Clamp01(1-radial*radial),.68f);float strata=.68f+.48f*Mathf.PerlinNoise(p.x/3+seed*.19f,p.y/3+seed*.33f);float plateau=Mathf.Floor(envelope*strata*6+.3f)/6;float rise=height*Mathf.Lerp(envelope*strata,plateau,.32f);points[z,x]=new Vector3(p.x,ground+rise-.16f,p.y);}for(int z=0;z<n;z++)for(int x=0;x<n;x++){if(((points[z,x]+points[z+1,x]+points[z,x+1]+points[z+1,x+1])/4-new Vector3(center.x,0,center.y)).y<0)continue;geo.Tri(points[z,x],points[z+1,x],points[z,x+1]);geo.Tri(points[z,x+1],points[z+1,x],points[z+1,x+1]);}}
static Mesh Save(Mesh source,string path){var m=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(!m){AssetDatabase.CreateAsset(source,path);return source;}m.Clear();m.indexFormat=source.indexFormat;m.vertices=source.vertices;m.triangles=source.triangles;m.uv=source.uv;m.normals=source.normals;m.RecalculateBounds();EditorUtility.SetDirty(m);UnityEngine.Object.DestroyImmediate(source);return m;}
static Renderer Child(GameObject g,string name,Mesh mesh,Material material){var go=new GameObject(name);go.transform.SetParent(g.transform,false);go.AddComponent<MeshFilter>().sharedMesh=mesh;var renderer=go.AddComponent<MeshRenderer>();renderer.sharedMaterial=material;return renderer;}
