string texturePath=Dir+"/Large Fractured Granite.png";var importer=(TextureImporter)AssetImporter.GetAtPath(texturePath);importer.wrapMode=TextureWrapMode.Repeat;importer.mipmapEnabled=true;importer.streamingMipmaps=true;importer.filterMode=FilterMode.Trilinear;importer.anisoLevel=4;importer.maxTextureSize=2048;foreach(string platform in new[]{"Android","iPhone"})importer.SetPlatformTextureSettings(new TextureImporterPlatformSettings{name=platform,overridden=true,maxTextureSize=2048,format=TextureImporterFormat.ASTC_6x6,compressionQuality=85});importer.SaveAndReimport();var texture=AssetDatabase.LoadAssetAtPath<Texture2D>(texturePath);var rockLayer=terrain.terrainData.terrainLayers[0];rockLayer.diffuseTexture=texture;EditorUtility.SetDirty(rockLayer);var alpha=terrain.terrainData.GetAlphamaps(0,0,512,512);for(int z=0;z<512;z++)for(int x=0;x<512;x++){float wx=terrain.transform.position.x+(x+.5f)/512*terrain.terrainData.size.x,wz=terrain.transform.position.z+(z+.5f)/512*terrain.terrainData.size.z;float grass=Mathf.Max(alpha[z,x,1],.28f+.25f*Mathf.PerlinNoise(wx/16+71,wz/16+29));alpha[z,x,1]=grass;alpha[z,x,0]=1-grass;}terrain.terrainData.SetAlphamaps(0,0,alpha);EditorUtility.SetDirty(terrain.terrainData);terrain.terrainData.SetBaseMapDirty();terrain.Flush();
