var line=File.ReadAllLines("FinalEnvironmentRoadReview/CoastalSnappedEdge.txt").Select(s=>{var v=s.Trim('(',')').Split(',');return new Vector2(float.Parse(v[0],System.Globalization.CultureInfo.InvariantCulture),float.Parse(v[1],System.Globalization.CultureInfo.InvariantCulture));}).ToArray();var batches=new Dictionary<Vector2Int,Pair>();int rocks=0;float length=0,next=18;for(int i=0;i<line.Length-1;i++){var e=line[i+1]-line[i];float segment=e.magnitude;var tangent=e.normalized;var normal=new Vector2(tangent.y,-tangent.x);while(next<=length+segment){var road=line[i]+tangent*(next-length);foreach(float row in Enumerable.Range(0,(int)R(1,5)).Select(j=>R(9,36))){float d=row+R(-2,2);var center=road+normal*d+tangent*R(-3,3);float radius=R(3.1f,10.5f);radius=Mathf.Min(radius,Mathf.Min(d-4.5f,43-d));bool inside=true;for(int k=0;k<8;k++)if(!Land(terrain,center+new Vector2(Mathf.Cos(k*Mathf.PI/4),Mathf.Sin(k*Mathf.PI/4))*radius*1.55f)){inside=false;break;}if(!inside)continue;float height=R(1.3f,8.5f)*Mathf.Lerp(.65f,1.3f,Mathf.InverseLerp(8,36,d));var key=new Vector2Int(Mathf.FloorToInt(center.x/65),Mathf.FloorToInt(center.y/65));if(!batches.TryGetValue(key,out var pair)){pair=new Pair();batches.Add(key,pair);}float rotation=R(0,Mathf.PI*2);int seed=random.Next(1000);Shape(pair.near,terrain,center,radius,height,rotation,9,seed);Shape(pair.far,terrain,center,radius,height,rotation,5,seed);rocks++;}next+=R(8,26);}length+=segment;}
